// PreCheck is a precheck that ensures test requirements, such as existing
// environment variables, are met. It should be included in every acc test.
func PreCheck(t *testing.T) {
	// if os.Getenv("TEST_LXD_REQUIRED_VAR") == "" {
	// 	t.Fatal("TEST_LXD_REQUIRED_VAR must be set for acceptance tests")
	// }
}

// PreCheckVMTests skips VM tests if the LXD_TEST_SKIP_VMS environment variable is set.
func PreCheckVMTests(t *testing.T) {
	if shared.IsTrue(os.Getenv("LXD_TEST_SKIP_VMS")) {
		t.Skipf("Test %q skipped. VM tests are disabled because LXD_TEST_SKIP_VMS is set.", t.Name())
	}
}

// PreCheckLxdVersion skips the test if the server's version does not satisfy
// the provided version constraints. The version constraints are detailed at:
// https://pkg.go.dev/github.com/hashicorp/go-version#readme-version-constraints
func PreCheckLxdVersion(t *testing.T, versionConstraint string) {
	p := testProvider()
	server, err := p.InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	apiServer, _, err := server.GetServer()
	if err != nil {
		t.Fatal(err)
	}

	serverVersion := apiServer.Environment.ServerVersion
	ok, err := utils.CheckVersion(serverVersion, versionConstraint)
	if err != nil {
		t.Fatalf("Failed to check LXD server version: %v", err)
	}

	if !ok {
		t.Skipf("Test %q skipped. LXD server version %q does not satisfy the version constraint %q", t.Name(), serverVersion, versionConstraint)
	}
}

// PreCheckAPIExtensions skips the test if the LXD server does not support
// the required extensions.
func PreCheckAPIExtensions(t *testing.T, extensions ...string) {
	p := testProvider()
	server, err := p.InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	missing := []string{}
	for _, e := range extensions {
		if !server.HasExtension(e) {
			missing = append(missing, e)
		}
	}

	if len(missing) > 0 {
		t.Skipf("Test %q skipped. LXD server is missing required extensions: %v", t.Name(), missing)
	}
}

// PreCheckVirtualization skips the test if the LXD server does not
// support virtualization.
func PreCheckVirtualization(t *testing.T) {
	p := testProvider()
	server, err := p.InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	apiServer, _, err := server.GetServer()
	if err != nil {
		t.Fatal(err)
	}

	// Ensure that LXD server supports qemu driver which is required for virtualization.
	if !strings.Contains(apiServer.Environment.Driver, "qemu") {
		t.Skipf("Test %q skipped. LXD server does not support virtualization.", t.Name())
	}
}

// PreCheckClustering skips the test if LXD server is not running
// in clustered mode. Additionally, it returns the cluster member
// names.
func PreCheckClustering(t *testing.T, minMembers int) []string {
	p := testProvider()
	server, err := p.InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	if !server.IsClustered() {
		t.Skipf("Test %q skipped. LXD server is not running in clustered mode.", t.Name())
	}

	// Extract cluster member names if not already done.
	clusterMembers, err := server.GetClusterMembers()
	if err != nil {
		t.Fatalf("Failed to retrieve cluster member names: %v", err)
	}

	// Ensure minimum number of members are available.
	if len(clusterMembers) < minMembers {
		t.Skipf("Test %q skipped. LXD cluster has %d members, but %d are required.", t.Name(), len(clusterMembers), minMembers)
	}

	// Extract cluster member names.
	clusterMemberNames := make([]string, 0, len(clusterMembers))
	for _, m := range clusterMembers {
		clusterMemberNames = append(clusterMemberNames, m.ServerName)
	}

	return clusterMemberNames
}

// PreCheckStandalone skips the test if LXD server is not running
// in standalone mode (or in other words if LXD is clustered).
func PreCheckStandalone(t *testing.T) {
	p := testProvider()
	server, err := p.InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	if server.IsClustered() {
		t.Skipf("Test %q skipped. LXD server is not running in standalone mode.", t.Name())
	}
}

// PreCheckServerTests skips the test unless the LXD_TEST_SERVER environment
// variable is set to a truthy value. Server tests modify global LXD server
// configuration and are therefore opt-in.
func PreCheckServerTests(t *testing.T) {
	if !shared.IsTrue(os.Getenv("LXD_TEST_SERVER")) {
		t.Skipf("Test %q skipped. LXD_TEST_SERVER is not set to %q.", t.Name(), "true")
	}
}

// PreCheckCeph skips the test unless a Ceph cluster is available for acceptance
// testing. It returns the Ceph cluster name, the CephFS file system name, and
// the Ceph Object Gateway endpoint, all read from the LXD_CEPH_CLUSTER,
// LXD_CEPH_CEPHFS, and LXD_CEPH_CEPHOBJECT_RADOSGW environment variables. These
// are set by the CI workflow when MicroCeph is installed on the test runner.
func PreCheckCeph(t *testing.T) (clusterName string, cephfsName string, radosgwEndpoint string) {
	clusterName = os.Getenv("LXD_CEPH_CLUSTER")
	cephfsName = os.Getenv("LXD_CEPH_CEPHFS")
	radosgwEndpoint = os.Getenv("LXD_CEPH_CEPHOBJECT_RADOSGW")

	if clusterName == "" || cephfsName == "" || radosgwEndpoint == "" {
		t.Skipf("Test %q skipped. Ceph environment variables (LXD_CEPH_CLUSTER, LXD_CEPH_CEPHFS, LXD_CEPH_CEPHOBJECT_RADOSGW) are not set.", t.Name())
	}

	return clusterName, cephfsName, radosgwEndpoint
}

// PreCheckRoot skips the test if the user cannot escalate privileges without a password.
// Root is required for certain tests, such as creating a loopback device for storage.
// This ensures tests do not stop midway asking for password.
func PreCheckRoot(t *testing.T) {
	err := exec.Command("sudo", "-n", "true").Run()
	if err != nil {
		t.Skipf("Test %q skipped. Cannot escalate privilege without a password.", t.Name())
	}
}

// PreCheckLocalServerHTTPS skips the test if the LXD server is not reachable over HTTPS.
// Additionally, it returns the server's HTTPS address. If the test remote is a unix
// socket, the local HTTPS address is used instead.
func PreCheckLocalServerHTTPS(t *testing.T) string {
	address := testRemotes()[testProviderRemoteName].Address
	if strings.HasPrefix(address, "unix://") {
		address = "https://127.0.0.1:8443"
	}

	conn, err := net.DialTimeout("tcp", strings.TrimPrefix(address, "https://"), 1*time.Second)
	if err != nil {
		t.Skipf("Test %q skipped. LXD server is not available on %q.", t.Name(), address)
	}

	_ = conn.Close()

	return address
}

// ConfigureTrustPassword sets and returns the trust password. If the server
// does not support trust password, the test is skipped.
func ConfigureTrustPassword(t *testing.T) string {
	password := "test-pass"

	// Only servers with LXD version < 6.0.0 support trust password.
	PreCheckLxdVersion(t, "< 6.0.0")

	server, err := testProvider().InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	apiServer, etag, err := server.GetServer()
	if err != nil {
		t.Fatal(err)
	}

	apiServer.Config["core.trust_password"] = password

	err = server.UpdateServer(apiServer.Writable(), etag)
	if err != nil {
		t.Fatal(err)
	}

	return password
}

// ConfigureBearerToken creates a bearer identity if it is missing, and issues a new bearer token.
// If the server does not support bearer tokens, the test is skipped.
func ConfigureBearerToken(t *testing.T) (token string, cleanup func()) {
	server, err := testProvider().InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	if server.CheckExtension("auth_bearer") != nil {
		t.Skipf("Test %q skipped. LXD server does not support bearer token authentication.", t.Name())
	}

	identityName := "tf-" + GenerateName(2, "-")

	// Create new identity.
	identityPost := api.IdentitiesBearerPost{
		Name:   identityName,
		Type:   api.IdentityTypeBearerTokenClient,
		Groups: []string{},
	}

	err = server.CreateIdentityBearer(identityPost)
	if err != nil {
		t.Fatal(fmt.Errorf("Failed to create bearer identity %q: %w", identityName, err))
	}

	cleanup = func() {
		err := server.DeleteIdentity(api.AuthenticationMethodBearer, identityName)
		if err != nil {
			t.Logf("Failed to delete bearer identity %q during cleanup: %v", identityName, err)
		}
	}

	// Issue token for the created identity.
	tokenPost := api.IdentityBearerTokenPost{}

	bearerToken, err := server.IssueBearerIdentityToken(identityName, tokenPost)
	if err != nil {
		cleanup()
		t.Fatal(fmt.Errorf("Failed to issue bearer token for identity %q: %w", identityName, err))
	}

	return bearerToken.Token, cleanup
}

// GenerateClientCertificate generates a new client certificate and key pair
// without adding the certificate to the server's trust store. Returns both
// PEM-encoded, along with a cleanup function that removes the certificate
// from the LXD trust store (in case it gets added during the test, e.g. via
// trust token).
func GenerateClientCertificate(t *testing.T) (clientCert string, clientKey string, cleanup func()) {
	certPEM, keyPEM, err := shared.GenerateMemCert(true, shared.CertOptions{AddHosts: false})
	if err != nil {
		t.Fatalf("Failed to generate client certificate: %v", err)
	}

	clientCert = string(certPEM)
	clientKey = string(keyPEM)

	certFingerprint, err := shared.CertFingerprintStr(clientCert)
	if err != nil {
		t.Fatalf("Failed to compute certificate fingerprint: %v", err)
	}

	cleanup = func() {
		server, err := testProvider().InstanceServer("", "", "")
		if err != nil {
			t.Logf("Failed to get server for certificate cleanup: %v", err)
			return
		}

		err = server.DeleteCertificate(certFingerprint)
		if err != nil && !errors.IsNotFoundError(err) {
			t.Logf("Failed to delete client certificate %q during cleanup: %v", certFingerprint, err)
		}
	}

	return clientCert, clientKey, cleanup
}

// RedeemTrustToken redeems a trust token that was issued for a pending TLS identity.
// It connects to the LXD server as an untrusted client and enrolls the given client certificate,
// which moves the identity out of the pending state.
func RedeemTrustToken(t *testing.T, token string, clientCert string, clientKey string) {
	// The token can only be redeemed on the server that issued it.
	address := PreCheckLocalServerHTTPS(t)

	// The client is not trusted yet, so the server certificate cannot be verified against a previously
	// accepted fingerprint.
	args := &lxd.ConnectionArgs{
		TLSClientCert:      clientCert,
		TLSClientKey:       clientKey,
		InsecureSkipVerify: true,
	}

	untrustedServer, err := lxd.ConnectLXD(address, args)
	if err != nil {
		t.Fatalf("Failed to connect to LXD server as an untrusted client: %v", err)
	}

	// Only the trust token may be provided.
	// LXD enrolls the client certificate that was presented during the TLS handshake.
	identityPost := api.IdentitiesTLSPost{
		TrustToken: token,
	}

	err = untrustedServer.CreateIdentityTLS(identityPost)
	if err != nil {
		t.Fatalf("Failed to redeem trust token: %v", err)
	}
}

// ConfigureMutualTLS generates a new client certificate and key, adds the
// certificate to the server's trust store, and returns the client certificate
// and the key (both PEM-encoded).
func ConfigureMutualTLS(t *testing.T) (clientCert string, clientKey string, cleanup func()) {
	clientCert, clientKey, cleanup = GenerateClientCertificate(t)

	// Decode PEM to get the DER bytes for base64 encoding.
	block, _ := pem.Decode([]byte(clientCert))
	if block == nil {
		t.Fatal("Failed to decode generated certificate PEM")
	}

	req := api.CertificatesPost{
		Name:        "tf-" + GenerateName(2, "-"),
		Type:        "client",
		Certificate: base64.StdEncoding.EncodeToString(block.Bytes),
	}

	server, err := testProvider().InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	// Add the client certificate directly to the server's trust store.
	err = server.CreateCertificate(req)
	if err != nil {
		t.Fatalf("Failed to add client certificate to trust store: %v", err)
	}

	return clientCert, clientKey, cleanup
}

// GetServerCertificateFingerprint retrieves the certificate fingerprint of the
// LXD server listening on https://127.0.0.1:8443.
func GetServerCertificateFingerprint(t *testing.T) string {
	serverCert, err := shared.GetRemoteCertificate(context.Background(), "https://127.0.0.1:8443", "test")
	if err != nil {
		t.Fatalf("Failed to get server certificate: %v", err)
	}

	return shared.CertFingerprint(serverCert)
}

// ConfigureTrustToken ensures the trust token is set to "test-pass". If the server
// does not support trust password, the test is skipped.
func ConfigureTrustToken(t *testing.T) string {
	server, err := testProvider().InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	// Create new token.
	tokenPost := api.CertificatesPost{
		Name:  "tf-test-token",
		Type:  "client",
		Token: true,
	}

	op, err := server.CreateCertificateToken(tokenPost)
	if err != nil {
		t.Fatal(err)
	}

	opAPI := op.Get()
	token, err := opAPI.ToCertificateAddToken()
	if err != nil {
		t.Fatal(err)
	}

	return token.String()
}

// PrintResourceState is a test check function that prints the entire state
// of a resource with the given name. This check should be used only for
// debuging purposes.
//
// Example resource name: lxd_profile.profile2.
func PrintResourceState(t *testing.T, resName string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[resName]
		if !ok {
			return fmt.Errorf("Resource %q not found", resName)
		}

		fmt.Println(utils.ToPrettyJSON(rs))
		return nil
	}
}

// InstanceServer returns an LXD instance server connected to the default test
// remote and project. Use it when a test needs to interact with the cluster
// directly, for example to set up or verify state outside the provider.
func InstanceServer(t *testing.T) lxd.InstanceServer {
	server, err := testProvider().InstanceServer("", "", "")
	if err != nil {
		t.Fatal(err)
	}

	return server
}

